from pathlib import Path
import argparse,html
p=argparse.ArgumentParser();p.add_argument('--output-dir',type=Path);p.add_argument('--hosted',action='store_true');args=p.parse_args()
r=Path(__file__).resolve().parents[1];out=args.output_dir or r
E=html.escape
prefix='' if args.hosted else 'https://metadata-gtm-workshops.vercel.app/gtm-part1/'
def video(key,title,poster,duration):
 return '<video class="workshop-video" id="'+key+'" controls playsinline preload="none" poster="'+prefix+'media/'+poster+'" aria-label="'+E(title)+'"><source src="'+prefix+'media/'+key+'.mp4" type="video/mp4">Open the workshop site to watch this recording.</video><p class="media-caption" data-video-note="'+key+'">'+duration+' · <a href="https://metadata-gtm-workshops.vercel.app/gtm-part1/Recordings.html#'+key+'">Watch on the password-protected workshop site</a></p>'
jumps=[(365,'06:05','Clone the project'),(673,'11:13','Company brief and setup'),(1039,'17:19','Research the targets'),(1309,'21:49','Build the first page'),(1518,'25:18','Review the page'),(2005,'33:25','Save the skill'),(2190,'36:30','Reuse it for Okta'),(2719,'45:19','Check the saved files')]
